import {createHomework} from './homework-ui.js';
import {startFocus,focusLeft,resumeFocus,pauseFocus,recoverFocus,clockInterrupted} from './focus-core.js';
import {DemoBridge} from './bridge-client.js';
import {PRIVATE_KEY,PUBLIC_KEY,SCOPES,PLACES,makeId,emptyPrivate,privateState,publicState,saveThought,displayNotices,statusOf,publishNotice,changeNotice,exportPublic,inspectPublic,importPublic,audit} from './round2-core.js';

export function createRound2(h){
 const {esc,I,modal,close,toast,download}=h,$=s=>document.querySelector(s);
 let personal=read(PRIVATE_KEY,privateState),pub=read(PUBLIC_KEY,publicState),current='',interval=null,screenHidden=false,clockFault=false,lastClock=Date.now(),lastTick=performance.now(),pendingImport=[],draftNotice=null,noticeFilter='active',classTimer={end:0,left:300},focusTickAt=Date.now(),focusMono=performance.now(),noticeCursor=0,redrawing=false;
 const portable=location.protocol==='file:';
 personal.focus=recoverFocus(personal.focus);
 let syncInfo={state:'local',lastReceived:pub.sync?.lastReceived||null},adapterFollow=false;
 const bridge=new DemoBridge(info=>{syncInfo=info;document.querySelectorAll('[data-sync-status]').forEach(e=>e.textContent=syncLabel());if(bridge?.connected&&info.state!=='online')document.querySelectorAll('[data-server-write]').forEach(e=>e.disabled=true)},snapshot=>{
  const oldMode=pub.mode,oldHidden=pub.hidden;pub.notices=snapshot.notices;pub.assignments=snapshot.assignments||[];pub.audit=snapshot.audit;pub.role=['teacher','admin'].includes(snapshot.identity.role)?snapshot.identity.role:'student';pub.scope=snapshot.identity.scope;pub.bridge=snapshot.bridge;pub.sync={revision:snapshot.revision,lastReceived:new Date().toISOString()};
  const b=snapshot.bridge,n=snapshot.courseNote,confirmed=!!(b.available&&!b.conflict&&n?.confirmed&&n.subject===b.next);pub.course={next:b.available?b.next:'来源不可用',note:confirmed?n.text:'',confirmed,conflict:b.conflict||!!(n&&n.subject!==b.next)};pub.mode=oldMode;pub.hidden=oldHidden;if(adapterFollow&&!pub.hidden)pub.mode=b.available&&!b.conflict?b.state:'class';saveC();
  if(current==='classroom'&&$('#screen-content')){$('#screen-content').innerHTML=screenContent();document.querySelectorAll('[data-r2^="mode:"]').forEach(e=>e.setAttribute('aria-pressed',String(e.dataset.r2==='mode:'+pub.mode)))}if(['resources','homework','assignments'].includes(current))refresh();if($('#r2-public-activities'))$('#r2-public-activities').outerHTML=publicActivities();document.querySelectorAll('[data-server-write]').forEach(e=>e.disabled=false);
 });
 if(bridge.connected)queueMicrotask(()=>bridge.start());
 function syncLabel(){const labels={local:'本机演示 · 无远程服务',connecting:'连接中 · 只读缓存',online:'本地演示服务已连接',offline:'服务离线 · 只读缓存',unauthorized:'凭据失效 · 只读缓存'};return (labels[syncInfo.state]||'状态未知')+(pub.sync?.lastReceived?' · 最近接收 '+date(pub.sync.lastReceived):'')}
 function connectionBar(){if(portable)return '<div class="sync-bar">便携单机演示 · 不依赖网络服务 · 私人记录与公共内容分开保存</div>';return `<div class="sync-bar"><span data-sync-status>${syncLabel()}</span>${act(bridge.connected?'连接与来源':'连接本地演示服务','connect-dialog','text-link')}</div>`}
 function courseReadout(){const b=pub.bridge;const rows=b?.available?b.schedule:b?[]:[{period:'第三节',time:'10:10–10:50',subject:'语文'},{period:'第四节',time:'11:00–11:40',subject:'物理'},{period:'第五节',time:'14:30–15:10',subject:'数学'}];return `<div class="readonly-course"><div><span>当前 / ${b?'模拟适配器':'手动样例'}</span><strong>${esc(b?(b.available?b.current:'课程来源不可用'):'语文（示例）')}</strong></div><div><span>下一节</span><strong>${esc(b?(b.available?b.next:'等待来源恢复'):pub.course.next)}</strong></div></div><div class="readonly-schedule">${rows.map(r=>`<span>${esc(r.period)} <b>${esc(r.subject)}</b><small>${esc(r.time)}</small></span>`).join('')}</div><small>只读课表示例 · ${b?esc(b.label):'未接通 ClassIsland'} · 不构成学校真实安排</small>`}
 function ensureWrite(){if(bridge.connected&&bridge.state!=='online')throw Error('服务当前只读。请等待重新连接后再发布或修改。')}
 function connectDialog(){modal('本地演示服务与课程来源',`<p data-sync-status>${syncLabel()}</p>${bridge.connected?`<p>身份：${esc(bridge.identity?.name||'待连接')} · ${esc(bridge.identity?.scope||'')}<br>课程源：${esc(pub.bridge?.label||'等待数据')}<br>消息快照版本：${pub.sync?.revision||0}</p><div class="row-actions">${act('重新拉取最新内容','sync-pull','outline')}${act('断开并回到本机演示','sync-disconnect','text-link')}</div><label class="checkbox-label"><input type="checkbox" id="follow-adapter" ${adapterFollow?'checked':''}>本窗口跟随模拟课程状态（教师手动隐藏优先）</label>${pub.role==='admin'?`<p>仅驱动本地模拟器，不控制真实 ClassIsland：</p><div class="row-actions">${act('模拟上课','adapter:class','outline')}${act('模拟课间','adapter:break','outline')}${act('模拟放学','adapter:after','outline')}${act('模拟来源未启动','adapter:unavailable','outline')}${act('模拟课表冲突','adapter:conflict','outline')}</div>`:''}`:`<p>源码目录运行 <code>node scripts/classroom-server.mjs</code>，再打开它提供的 localhost 地址。本服务只用于本机实验，不能接入学校生产设备。</p><form data-r2-form="connect"><label>本地演示凭据（不是教师账号密码）<input name="token" type="password" autocomplete="off" required maxlength="128" placeholder="从 .haiz-demo/local-demo-keys.json 复制相应凭据"></label><button class="btn primary">连接并读取授权范围</button></form>`}<p class="muted">没有摄像头、录音、注意力监测或远程命令功能。凭据只保存在本标签页的会话存储，私人学习记录不发送给服务。</p>`,true)}

 const roleName={teacher:'教师',admin:'授权管理员',student:'学生只读'},modeName={class:'上课',break:'课间',after:'放学'},kindName={notice:'班级通知',activity:'公共活动',resource:'学习资源'},stateName={live:'展示中',scheduled:'待展示',pending:'待审核',archived:'已到期归档',withdrawn:'已撤回'};
 const act=(label,a,cls='outline',icon='')=>`<button class="btn ${cls}" data-r2="${a}">${icon?I(icon,18):''}${label}</button>`;
 const eyebrow=s=>`<span class="eyebrow">${s}</span>`;
 function read(key,validate){try{return validate(JSON.parse(localStorage.getItem(key)))}catch{return validate(null)}}
 function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch{toast('本机保存受限，请使用导出备份。关闭窗口后记录可能丢失。');return false}}
 const saveP=()=>persist(PRIVATE_KEY,personal),saveC=()=>persist(PUBLIC_KEY,pub);
 if(personal.focus)saveP();
 const refresh=()=>{redrawing=true;try{h.render()}finally{redrawing=false}};
 const homework=createHomework({esc,I,modal,close,toast,refresh,bridge,connectionBar,getState:()=>pub,saveState:value=>{pub=value;saveC()}});
 const active=()=>personal.thoughts.find(x=>x.id===personal.active)||personal.thoughts[0];
 const date=s=>new Date(s).toLocaleString('zh-CN',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
 function nav(which){return `<nav class="r2-subnav" aria-label="学习与教室导航"><div>${[['study','我的自习室'],['assignments','今日作业'],['shelf','思考书架'],['resources','公共资源']].map(([r,l])=>`<a href="#${r}" ${which===r?'aria-current="page"':''}>${l}</a>`).join('')}</div><span>${I('shield',14)} 私人记录只在此设备</span></nav>`}
 function study(){if(personal.focusDesk&&personal.focus)return focusDesk();const a=active(),p=PLACES[personal.place];return `<main id="main" class="r2-page study2 ${personal.toolsOnly?'tools-only':''}" data-space="${personal.place}">${nav('study')}<div class="r2-heading"><div>${eyebrow('HAIZ STUDY / THOUGHTS, CONTINUED')}<h1>学习可以暂停。<br><em>思路不必重来。</em></h1><p>先接回一个念头，再从一件小事开始。</p></div><div class="r2-heading-actions">${act(personal.toolsOnly?'显示学习空间':'只留下学习工具','tools','text-link',personal.toolsOnly?'leaf':'book')}<a class="text-link" href="#paper">${I('download',16)} 带到纸上</a></div></div><div class="continuity-layout"><section class="continuity-card"><div class="section-heading"><span class="pill">${I('edit',14)} ${a?'留给下一次的你':'你的第一张思路卡'}</span><span class="muted">私密 · 本机</span></div>${a?`<h2>${esc(a.title)}</h2><div class="context-line"><span>已经走到</span><p>${esc(a.understood||'还没有记录，也可以直接开始。')}</p></div>${a.tried?`<div class="context-line"><span>试过的路</span><p>${esc(a.tried)}</p></div>`:''}${a.stuck?`<div class="context-line"><span>暂时卡在</span><p>${esc(a.stuck)}</p></div>`:''}<div class="next-step"><span>下一步，只做这件事</span><p>${esc(a.next)}</p></div><div class="row-actions">${act('进入专注书桌','focus-open','primary','arrow')}${act('接着想下去','resume','text-link')}${act('更新思路','thought:'+a.id,'text-link')}</div>`:`<h2>还记得上次，<br>想到哪里了吗？</h2><p class="card-intro">不用重新制定计划。记下已经理解的、试过的方法，和一个容易开始的动作。</p><div class="example-thought"><span>一张卡可以这样写 · 示例</span><p>已经证明两个三角形相似。<br>下一步：用对应边，写出一个比例式。</p></div><div class="row-actions">${act('开始一件小事','gentle','primary','arrow')}${act('留下已有思路','thought','text-link')}</div>`}<div class="continuity-bottom"><span>${a?'不必现在完成。线索已经留下了。':'没有签到，也没有“落后”这回事。'}</span>${a?act('换一件小事','gentle','text-link'):''}</div></section><section class="space-preview space-${personal.place}"><img src="${p.image}" alt="${p.name}的概念学习空间，非实景照片"><div class="space-scrim"></div><span class="space-top">${I('volume',15)} 声音默认关闭 · 静态低耗电</span><div class="space-title">${eyebrow(p.en)}<h2>${p.name}</h2><p>${p.purpose}</p></div><div id="r2-room"></div><div class="space-bottom">${!portable?act('走近三维窗台','r2room','cream','play'):''}<span>概念空间 / 可随时收起</span></div></section></div><section class="study-invitation"><div><span class="eyebrow">A LITTLE WHILE, JUST FOR THIS</span><h2>关掉其他声音，<br>只和一个问题待一会儿。</h2><p>选择一小段时间。中断时把线索留下，回来时接着走。</p></div>${act(personal.focus&&personal.focus.status!=='done'?'回到我的书桌':'打开专注书桌','focus-open','primary','arrow')}</section><section class="space-section"><div class="section-heading"><h2>给不同的思考，找一个位置。</h2><span class="muted">每个地方，保留它自己的便笺。</span></div><div class="space-tabs">${Object.entries(PLACES).map(([key,v],i)=>`<button data-r2="space:${key}" aria-pressed="${personal.place===key}"><span class="space-symbol">${I(['leaf','book','moon','sun'][i],24)}</span><strong>${v.name}</strong><small>${v.purpose}</small><span class="space-selected">${I('check',16)}</span></button>`).join('')}</div></section><section id="thought-workspace" class="thinking-workspace"><div><span class="eyebrow">RIGHT HERE, RIGHT NOW</span><h2>${esc(p.prompt)}</h2><p>${esc(p.hint)}</p><label for="space-note" class="sr-only">${p.name}的私人便笺</label><textarea id="space-note" maxlength="2000" placeholder="写给自己，不需要标准答案。">${esc(personal.spaceNotes[personal.place]||'')}</textarea><div class="space-task-action">${act({tree:"把这句理解收进书架",library:"整理推理的四条线索",rain:"只留下书写工具",pond:"把想法变成下一步"}[personal.place],"space-tool","text-link")}<span>${{tree:"用自己的话复述",library:"理解 / 尝试 / 卡点 / 下一步",rain:"不打断连续表达",pond:"从回顾进入行动"}[personal.place]}</span></div><div class="note-actions"><small id="r2-save-state">${p.name} · 仅保存在本机</small>${act('把思路留下来','thought:'+(a?.id||''),'primary','edit')}</div></div><aside><span class="shelf-mark">${I('book',32)}</span><h3>有些进步，<br>不需要数字来证明。</h3><p>一个终于弄懂的问题，<br>一次被自己推翻的判断。</p><a class="text-link" href="#shelf">去思考书架 ${I('arrow',16)}</a><div class="divider"></div>${!portable?'<a class="text-link" href="#windowsill">打开第一轮窗台与计时器 ↗</a>':''}<a class="text-link block-link" href="#resources">看看老师留下的公共资源 ↗</a></aside></section><div class="private-controls">${act('导出私人备份','export-private','text-link','download')}<label class="text-link import-label">恢复私人备份<input type="file" id="private-import" accept="application/json,.json"></label>${act('管理思路记录','history','text-link')}${act('清除私人数据','clear-private','text-link')}</div><p class="r2-footnote">随时离开，没有退出惩罚。个人思路不会进入教室屏或公共内容包。${portable?'便携版不加载三维场景。':'三维窗台 © 幡幡 / TangfanOVO · AGPL-3.0，<a href="room/source.html">来源与完整源码</a>。'}</p></main>`}

 function focusDesk(){const f=personal.focus,p=PLACES[personal.place],a=personal.thoughts.find(x=>x.id===f.thoughtId),ready=f.status==='ready';return `<main id="main" class="focus-desk ${personal.toolsOnly?'focus-low':''}" data-space="${personal.place}"><img class="focus-landscape" src="${p.image}" alt="${p.name}概念空间"><div class="focus-shade"></div><header class="focus-top"><button data-r2="focus-leave">${I('arrow',16)} 返回自习室</button><span>HAIZ <b>STUDY</b></span><button data-r2="tools">${personal.toolsOnly?'显示风景':'低负荷模式'}</button></header><div class="focus-layout"><aside class="focus-context"><span class="eyebrow">THE THREAD YOU LEFT</span><h2>线索在这里。</h2>${[['已经理解',a?.understood],['试过的方法',a?.tried],['还没想通',a?.stuck]].map(([label,v])=>`<section><span>${label}</span><p>${esc(v||'暂时留白，也没关系。')}</p></section>`).join('')}<button class="focus-context-edit" data-r2="thought:${esc(f.thoughtId)}">整理这段思路 ↗</button></aside><section class="focus-center"><span class="eyebrow">${p.en} / A QUIET DESK</span><h1>${esc(f.title)}</h1><p class="focus-next">${esc(a?.next||f.next)}</p><div class="focus-clock" aria-label="剩余时间" data-focus-clock>25:00</div><div class="focus-duration" aria-label="选择本次时长">${[5,15,25,45].map(m=>`<button data-r2="focus-duration:${m}" aria-pressed="${f.minutes===m}" ${f.status==='running'?'disabled':''}>${m} 分钟</button>`).join('')}</div><p class="focus-state" role="status">${ready?'这一小段结束了。给下次留一步就好。':f.status==='running'?'只做眼前这一小步。随时可以停下。':esc(f.reason||'不急，准备好了再开始。')}</p><div class="focus-actions">${!ready?act(f.status==='running'?'暂停一会儿':'开始这一小段','focus-toggle','cream',f.status==='running'?'pause':'play'):''}${act('留下线索，结束这一段','focus-wrap','outline')}</div><p class="focus-note">静音 · 无排名 · 离开页面时暂停 · 时间只属于你</p></section><aside class="focus-note-card"><span class="eyebrow">A NOTE TO YOUR FUTURE SELF</span><h2>想到哪，写到哪。</h2><label class="sr-only" for="focus-checkpoint">专注时的私人线索</label><textarea id="focus-checkpoint" maxlength="2000" placeholder="一个公式，一句没写完的话。回来时不用重新找。">${esc(f.checkpoint)}</textarea><small id="focus-save-state">自动保存 · 只在此设备</small><div class="focus-paper-link"><a href="#paper">带到纸上，继续想 ↗</a></div></aside></div><footer class="focus-footer"><span>${p.name} / 静态概念空间</span><div>${Object.entries(PLACES).map(([key,v])=>`<button data-r2="space:${key}" aria-pressed="${personal.place===key}">${v.name}</button>`).join('')}</div><span>不用一直看着屏幕。</span></footer></main>`}
 function updateFocus(){const f=personal.focus;if(!f)return;const now=Date.now(),mono=performance.now();if(f.status==='running'&&clockInterrupted(now-focusTickAt,mono-focusMono)){personal.focus=pauseFocus(f,focusTickAt,'设备休眠或时间变化，已暂停。线索仍然保留。');saveP();refresh();return}focusTickAt=now;focusMono=mono;const left=focusLeft(f,now);if(f.status==='running'&&left===0){personal.focus=pauseFocus(f,now);saveP();refresh();return}const el=$('[data-focus-clock]');if(el){const sec=Math.ceil(left/1000);el.textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0')}}
 function wrapFocus(){personal.focus=pauseFocus(personal.focus);saveP();refresh();const f=personal.focus,a=personal.thoughts.find(t=>t.id===f.thoughtId);modal('收好这一段，再出发。',`<form data-r2-form="focus-wrap"><p class="muted">不必完成整个任务。保留你真正想到的地方就好。</p><label>这次多弄清楚了什么<textarea name="understood" maxlength="2000">${esc(f.checkpoint||a?.understood||'')}</textarea></label><label>回来后，最容易开始的一步<input name="next" required maxlength="500" value="${esc(a?.next||f.next)}"></label><button class="btn primary">保存线索，合上书桌</button></form>`)}
 const shelfKinds={understood:'终于理解',changed:'改变认识',question:'有价值的问题',exploring:'尚未完成的探索'};
 function shelf(){return `<main id="main" class="r2-page">${nav('shelf')}<div class="r2-heading"><div>${eyebrow('THE THINKING SHELF')}<h1>曾经不懂的，<br><em>正在变得清楚。</em></h1><p>这里收下理解的变化，也给没有答案的问题留位置。</p></div>${act('留下一点变化','shelf-new','primary','plus')}</div><div class="shelf-grid">${personal.shelf.length?personal.shelf.map((s,i)=>`<article class="shelf-card"><span class="eyebrow">${String(i+1).padStart(2,'0')} / ${shelfKinds[s.kind]}</span><h2>${esc(s.title)}</h2><span class="shelf-label">之前的我</span><p>${esc(s.before||'从一个问题开始。')}</p><div class="shelf-rule"></div><span class="shelf-label">此刻的理解 / 还想知道</span><p>${esc(s.after)}</p><div class="shelf-actions"><time>${date(s.updatedAt)}</time>${act('编辑','shelf-edit:'+s.id,'text-link')}${act('删除','shelf-delete:'+s.id,'text-link')}</div></article>`).join(''):`<section class="shelf-empty">${I('book',54)}<h2>不用攒够什么，才值得记录。</h2><p>试着留下一次“原来是这样”。<br>或者，留下一个还没有想明白的问题。</p>${act('写下第一条','shelf-new','primary')}</section>`}</div><div class="private-controls">${act('导出私人备份','export-private','text-link')}<a href="#study" class="text-link">返回我的自习室 ↗</a></div></main>`}
 function paper(){const a=active();return `<main id="main" class="r2-page paper-page"><div class="r2-heading no-print"><div>${eyebrow('LEARNING BEYOND THE SCREEN')}<h1>把屏幕关掉，<br><em>思考继续。</em></h1><p>这张卡可以带走。回来时，从同一条线索继续。</p></div><div class="row-actions">${act('打印这一页','print','primary','download')}<a href="#study" class="text-link">返回思路 ↗</a></div></div><article class="paper-card"><header><strong>HAIZ STUDY</strong><span>一页思路续接卡 / 仅供自己</span></header><h2>${esc(a?.title||'今天，我想弄清楚……')}</h2><div class="paper-first"><b>先做这个小动作</b><p>${esc(a?.next||'翻开一页、读一道题，或写下一句已经知道的话。')}</p></div>${[['我已经理解到哪里',a?.understood],['我试过的方法',a?.tried],['我卡住的地方',a?.stuck],['离开前，给下次留一步','']].map(([l,v])=>`<section><h3>${l}</h3><p>${esc(v||'')}</p><div class="writing-lines"></div></section>`).join('')}<footer>不用一直看屏幕。回来后打开「我的自习室 → 更新思路」，把纸上的下一步接回桌面。<br>不计分、不排名；不需要手机或扫码。</footer></article></main>`}
 function resources(){const list=pub.notices.filter(n=>n.kind==='resource'&&statusOf(n)==='live'&&[pub.scope,SCOPES[2]].includes(n.scope));return `<main id="main" class="r2-page">${nav('resources')}${connectionBar()}<div class="r2-heading"><div>${eyebrow('FROM THE CLASSROOM, WITH CARE')}<h1>老师留下的，<br><em>一小份好奇心。</em></h1><p>公共选学资源。纸上想、在家看，都可以。</p></div><span class="pill">本机演示 · 非正式布置</span></div><div class="resource-grid">${list.length?list.map(n=>`<article class="resource-card"><span class="badge">教师内容 · 演示审核通过</span><h2>${esc(n.title)}</h2><p>${esc(n.body)}</p><div class="row-actions">${act('从这里开始','resource-start:'+n.id,'primary')}${act('打印资源','resource-print:'+n.id,'text-link')}</div><small>${esc(n.scope)} · 到期 ${date(n.endAt)}</small></article>`).join(''):'<div class="empty-state"><h2>现在没有待展示的公共资源。</h2><p>老师可以在发布台创建一条学习资源，确认后在本机同步。</p></div>'}</div><p class="r2-footnote">不提交答案、不公开个人学习记录。跨设备不会自动同步；教师可通过公共演示内容包传递，并在接收端重新审核。</p></main>`}
 function publicActivities(){const list=pub.notices.filter(n=>n.kind==='activity'&&statusOf(n)==='live'&&[pub.scope,SCOPES[2]].includes(n.scope));return `<section id="r2-public-activities" class="public-activities"><div class="section-heading"><div>${eyebrow('ALSO ON YOUR CLASSROOM SCREEN')}<h2>教室里看到的活动，在这里继续。</h2></div><span class="badge">已审公共演示</span></div>${list.map(n=>`<button class="public-activity-row" data-r2="public-activity:${n.id}"><strong>${esc(n.title)}</strong><span>${esc(n.body)}</span><small>${esc(n.scope)} · v${n.version||1} · 详情与线下参与方式 ↗</small></button>`).join('')||'<p>当前没有已审核的公共活动。</p>'}</section>`}
 function leave(){if(!redrawing&&personal.focus?.status==='running'){personal.focus=pauseFocus(personal.focus);saveP()}current='';clearInterval(interval);interval=null;$('#r2-room')?.replaceChildren();screenHidden=false}
 function render(route){current=route;return ({study,shelf,paper,resources,classroom,teach,homework:homework.workbench,assignments:homework.student})[route]?.()||''}
 function mount(){const quick=$('[data-r2-form=quick-publish]');if(quick){quick.addEventListener('input',saveTeacherDraft);quick.addEventListener('change',saveTeacherDraft);draftPreview()}if(current==='study'&&personal.focusDesk){focusTickAt=Date.now();focusMono=performance.now();interval=setInterval(updateFocus,1000);updateFocus();$('#focus-checkpoint')?.addEventListener('input',e=>{personal.focus.checkpoint=e.target.value;$('#focus-save-state').textContent=saveP()?'线索已保存 · 本机私密':'保存受限，请导出备份'})}lastClock=Date.now();lastTick=performance.now();if(current==='classroom'){interval=setInterval(tickScreen,1000);tickScreen()}const note=$('#space-note');if(note)note.addEventListener('input',()=>{personal.spaceNotes[personal.place]=note.value;$('#r2-save-state').textContent=saveP()?'已保存在这个空间 · 本机私密':'保存受限 · 请导出备份'});for(const [key,element] of [['private','#private-import'],['public','#public-import']])$(element)?.addEventListener('change',e=>readImport(e,key));try{const k='haiz.storage.check';localStorage.setItem(k,'1');localStorage.removeItem(k)}catch{toast('浏览器限制本机存储。请及时导出记录。')}}
 function thoughtForm(key){const a=personal.thoughts.find(x=>x.id===key)||{},note=personal.spaceNotes[personal.place]||'';modal('给下一次的你，留一条线索。',`<form id="thought-form" data-r2-form="thought" data-id="${esc(a.id||'')}"><p class="muted">打开卡片 → 写下线索 → 保存。只需标题和下一步，其余可以留空。</p><label>正在想什么<input name="title" maxlength="100" required value="${esc(a.title||personal.startDraft.title||'')}" placeholder="例如：相似三角形这道题"></label><div class="form-columns"><label>已经理解到哪里<textarea name="understood" maxlength="2000" placeholder="已经证明了什么？">${esc(a.understood||note)}</textarea></label><label>刚才试过什么<textarea name="tried" maxlength="2000" placeholder="尝试过的方法，不必完整">${esc(a.tried||'')}</textarea></label></div><label>暂时卡在哪一步<textarea name="stuck" maxlength="2000" placeholder="一个具体的疑问">${esc(a.stuck||'')}</textarea></label><label>下次最容易开始的一步<input name="next" maxlength="500" required value="${esc(a.next||personal.startDraft.next||'')}" placeholder="例如：用对应边写出一个比例式"></label><button class="btn primary">保存这段思路 ${I('check',18)}</button></form>`,true)}
 function gentle(step=1){modal(step===1?'今天，想解决什么？':'把它变成一个很小的开始。',`<form data-r2-form="gentle-${step}"><span class="eyebrow">GENTLE START / ${step} OF 3</span>${step===1?`<label>一件事就好<input name="title" maxlength="100" required value="${esc(personal.startDraft.title||'')}" placeholder="例如：复习物理"></label><p class="muted">不需要安排整个晚上。</p>`:`<p>${esc(personal.startDraft.title)}</p><label>现在能做的第一个动作<input id="gentle-next" name="next" maxlength="500" required value="${esc(personal.startDraft.next||'')}" placeholder="例如：先看昨天没弄懂的那道题"></label><div class="gentle-suggestions">${['翻开上次停下的那一页','读一遍昨天没弄懂的题','写下目前已经知道的一点'].map((s,i)=>act(s,'suggest:'+i,'outline')).join('')}</div><p class="muted">这是固定提示，不是 AI 推理。选一个，或写自己的。</p>`}<button class="btn primary">${step===1?'下一步':'进入学习空间'} ${I('arrow',17)}</button></form>`)}
 function shelfForm(key){const s=personal.shelf.find(x=>x.id===key)||{};modal('留下一点理解的变化。',`<form data-r2-form="shelf" data-id="${esc(s.id||'')}"><label>这是一条<select name="kind">${Object.entries(shelfKinds).map(([k,l])=>`<option value="${k}" ${s.kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label>给它一个名字<input name="title" maxlength="100" required value="${esc(s.title||'')}"></label><label>之前怎样理解 / 问题从哪里来<textarea name="before" maxlength="2000">${esc(s.before||'')}</textarea></label><label>现在的理解 / 仍然想探索的<textarea name="after" required maxlength="2000">${esc(s.after||'')}</textarea></label><p class="muted">仅保存在本机，可以编辑、导出和删除。</p><button class="btn primary">放上思考书架</button></form>`)}
 async function readImport(event,kind){const file=event.target.files?.[0];if(!file)return;try{if(file.size>1048576)throw Error('请选择小于 1 MB 的 JSON 备份。');const raw=JSON.parse(await file.text());if(kind==='public'){pendingImport=inspectPublic(raw);modal('先看看带来的公共内容。',`<p>这是未签名的演示包，不代表学校授权。确认后仍需逐条审核。</p><ul>${pendingImport.map(n=>`<li>${esc(n.title)} · ${esc(n.scope)}</li>`).join('')}</ul>${act('导入待审区','import-confirm','primary')}`)}else{if(raw?.format!=='haiz-private-study'||raw.version!==2||!Array.isArray(raw.data?.thoughts)||!Array.isArray(raw.data?.shelf))throw Error('这不是 HAIZ 私人学习备份。');const restored=privateState(raw.data);pendingImport=restored;modal('恢复这份私人备份？',`<p>含 ${restored.thoughts.length} 条思路和 ${restored.shelf.length} 条思考记录。将替换当前设备上的 Study 2.0 私人记录；不会修改第一轮便笺或公共通知。可先取消并导出当前备份。</p>${act('确认替换私人记录','private-restore','primary')}`)}}catch(e){toast(e.message)}event.target.value=''}

 // Public display and teacher workspace share only PUBLIC_KEY. Personal records never enter these views.
 function classTools(){return `<div class="screen-tools"><button data-r2="screen-hide">${I('close',18)} 一键隐藏</button><button data-r2="fullscreen">${I('box',18)} 全屏展示</button><a href="#teach">教师发布台 ↗</a></div>`}
 function classroom(){return `<main id="main" class="classroom-page"><div class="classroom-bar"><a href="#world" class="classroom-brand">HAIZ<span>CLASSROOM</span></a><div class="screen-mode" aria-label="手动展示模式">${Object.entries(modeName).map(([k,v])=>`<button data-r2="mode:${k}" aria-pressed="${pub.mode===k}">${v}</button>`).join('')}</div>${classTools()}</div><div class="screen-context"><span>${esc(pub.scope)} <i></i> 独立演示</span><span>ClassIsland 未连接 · ${adapterFollow?'跟随模拟课程':'手动模式'} · ${clockFault?'检测到时钟跳变，已收起内容':pub.homeworkAuto?'晚修按课表自动显示作业':'自动作业展示已暂停'}</span></div>${connectionBar()}<div id="screen-content">${screenContent()}</div><div id="screen-curtain" hidden><span>HAIZ 已隐藏</span><p>可以切回授课软件。不会自动重新出现。</p>${act('手动恢复','screen-show','cream')}</div><div class="classroom-bottom"><span>手动隐藏优先 · 普通通知仅在课间 / 放学展示</span><div>${act('课堂小工具','class-tools','text-link')}<a href="#resources">公共学习资源 ↗</a></div></div></main>`}
 function screenContent(){if(homework.visible()&&!clockFault)return homework.board();if(pub.hidden)return '<section class="class-quiet"><p>教师已隐藏本机公共内容。</p>'+act('手动恢复','screen-show','outline')+'</section>';if(pub.mode==='class')return `<section class="class-quiet"><span class="quiet-symbol">${I('book',38)}</span><span class="eyebrow">LESS DISTRACTION, MORE ROOM TO TEACH</span><h1>把屏幕，留给课堂。</h1><p>普通通知已收起。课表与铃声由 ClassIsland 负责。</p><div class="quiet-clock" data-screen-clock></div>${courseReadout()}<small>不置顶 · 不抢焦点 · 不触发系统提醒</small>${act('隐藏 HAIZ，开始授课','screen-hide','primary')}</section>`;const list=displayNotices(pub),reminders=list.filter(x=>x.kind==='notice'),n=reminders[noticeCursor%Math.max(1,reminders.length)],event=list.find(x=>x.kind===(pub.mode==='after'?'resource':'activity')),course=pub.course;return `<section class="classroom-hero"><div class="classroom-time"><span class="eyebrow">${pub.mode==='after'?'TAKE A LITTLE CURIOSITY HOME':'A LITTLE ROOM BETWEEN LESSONS'}</span><div data-screen-clock>--:--</div><p>${new Date().toLocaleDateString('zh-CN',{month:'long',day:'numeric',weekday:'long'})}</p><span class="mode-caption">${pub.mode==='after'?'今天，辛苦了。':'课间，松一口气。'}</span></div><article class="screen-notice"><div><span class="screen-pill">${n?.priority==='urgent'?'授权紧急演示':'班级提醒'}</span><span class="notice-index">01 / KEEP IN MIND</span></div><h1>${esc(n?.title||(pub.mode==='after'?'带着一点好奇心，回家。':'现在，没有需要记住的新通知。'))}</h1><p>${esc(n?.body||'留点空白也很好。')}</p><footer>${reminders.length>1?`<div class="notice-paging">${act('上一条','notice-prev','text-link')}<span>${noticeCursor%reminders.length+1} / ${reminders.length} 条提醒</span>${act('下一条','notice-next','text-link')}</div>`:''}<span>${n?`${roleName[n.publisherRole]}发布 · ${date(n.publishedAt)} · 演示审核通过`:'无需手机，也不会错过这里的公共内容'}</span><span>${n?'到期 '+date(n.endAt):'HAIZ CLASSROOM'}</span></footer></article></section><section class="classroom-lower"><article class="course-strip"><div>${I('book',24)}<span>${pub.mode==='after'?'教师准备事项':'下一节 / 手动示例'}</span></div><h2>${esc(course.next||'尚未设置')}</h2><p>${course.conflict?'发现冲突 · 等待教师确认，增强提示已暂停':course.confirmed?esc(course.note||'暂无附加提示'):'课程与提示尚未确认，不作为正式安排。'}</p><small>未连接 ClassIsland · 不修改原课表</small></article><article class="screen-activity"><span class="eyebrow">${pub.mode==='after'?'A QUESTION TO TAKE HOME':'SOMETHING TO LOOK FORWARD TO'}</span><h2>${esc(event?.title||'把空白留给休息。')}</h2><p>${esc(event?.body||'这里仅展示经过演示审核的公共活动。')}</p><a href="#${pub.mode==='after'?'resources':'club'}" class="text-link">${pub.mode==='after'?'打开公共资源':'在电脑上查看社团活动'} ↗</a>${event?.kind==='activity'&&event.eventAt?`<span class="activity-countdown" data-activity-countdown="${esc(event.eventAt)}">演示活动时间 ${date(event.eventAt)}</span>`:''}<small>${event?'演示活动 / 资源 · 非学校真实安排':''}</small></article></section>`}

 const noticeTemplates=[{name:'课前准备',kind:'notice',message:'明天第一节，请带好课本和练习本。\n提前放进书包就好。'},{name:'活动提醒',kind:'activity',message:'本周活动提醒（请填写实际安排）\n时间：\n地点：\n线下参与方式：'},{name:'公共资源',kind:'resource',message:'留给大家的一道思考题\n请填写公开学习内容。无需上传个人答案。'}];
 const draftKey=()=>`haiz.teacher.draft.v1:${bridge.connected?bridge.identity?.name||'connected':'local'}:${pub.role}:${pub.scope}`;
 function teacherDraft(){try{const d=JSON.parse(localStorage.getItem(draftKey()));return {message:typeof d?.message==='string'?d.message.slice(0,2000):'',kind:['notice','activity','resource'].includes(d?.kind)?d.kind:'notice',expiry:['today','tomorrow','week'].includes(d?.expiry)?d.expiry:'tomorrow'}}catch{return {message:'',kind:'notice',expiry:'tomorrow'}}}
 function draftPreview(){const form=$('[data-r2-form=quick-publish]');if(!form)return;const message=form.elements.message.value.trim(),preview=$('#teacher-live-message');if(preview)preview.textContent=message||'你写下的话，会这样安静地出现在课间。';const label=$('#teacher-live-kind');if(label)label.textContent=kindName[form.elements.kind.value]||'班级通知'}
 function saveTeacherDraft(){const form=$('[data-r2-form=quick-publish]');if(!form)return;const d={message:form.elements.message.value,kind:form.elements.kind.value,expiry:form.elements.expiry.value};const saved=persist(draftKey(),d);if($('#teacher-draft-state'))$('#teacher-draft-state').textContent=saved?'草稿已保存 · 仅此设备':'保存受限，请复制留存';draftPreview()}
 function applyTemplate(index){const t=noticeTemplates[index],form=$('[data-r2-form=quick-publish]');if(!t||!form)return;form.elements.message.value=t.message;form.elements.kind.value=t.kind;saveTeacherDraft();close();form.elements.message.focus()}
 function teach(){const draft=teacherDraft();const list=pub.notices.filter(n=>noticeFilter==='active'?!['archived','withdrawn'].includes(statusOf(n)):['archived','withdrawn'].includes(statusOf(n)));return `<main id="main" class="r2-page teacher2"><div class="r2-subnav"><div><a href="#homework">今日作业</a><a href="#teach" aria-current="page">公共通知</a><a href="#desk">第一轮工作台</a><a href="#classroom">教室公共屏 ↗</a></div><label>演示角色 <select id="r2-role" ${bridge.connected?'disabled':''}>${Object.entries(roleName).map(([k,v])=>`<option value="${k}" ${pub.role===k?'selected':''}>${v}</option>`).join('')}</select></label></div>${connectionBar()}<div class="r2-heading"><div>${eyebrow('ONE NOTE, IN THE RIGHT PLACE')}<h1>说一遍，<br><em>在合适的时候看见。</em></h1><p>选好班级，写下一件事。发布前，再看一眼。</p></div><a class="btn outline" href="#classroom">预览教室屏 ${I('arrow',18)}</a></div><div class="publish-layout"><section class="publish-card"><div class="section-heading"><h2>给班级留句话</h2><span class="pill">${roleName[pub.role]}演示</span></div>${pub.role==='student'?'<div class="empty-state"><h3>学生端只读</h3><p>普通学生不能向教室大屏发布内容。</p></div>':`<form data-r2-form="quick-publish"><div class="notice-templates" aria-label="常用通知模板">${noticeTemplates.map((t,i)=>`<button type="button" data-r2="notice-template:${i}">${t.name} ↗</button>`).join('')}</div><label>送到哪个班<select name="scope" id="r2-scope" ${bridge.connected?'disabled':''}>${SCOPES.slice(0,pub.role==='admin'?3:2).map(s=>`<option ${s===pub.scope?'selected':''}>${s}</option>`).join('')}</select></label><label>想提醒大家什么<textarea name="message" required maxlength="2000" placeholder="明天第一节带作文纸。">${esc(draft.message)}</textarea><small id="teacher-draft-state" role="status">${draft.message?'已恢复本机草稿':'输入时自动保存草稿'}</small></label><div class="publish-options"><label>内容类型<select name="kind">${Object.entries(kindName).map(([k,v])=>`<option value="${k}" ${draft.kind===k?'selected':''}>${v}</option>`).join('')}</select></label><label>展示到<select name="expiry"><option value="tomorrow" ${draft.expiry==='tomorrow'?'selected':''}>明天放学（18:00）</option><option value="today" ${draft.expiry==='today'?'selected':''}>今天结束（23:59）</option><option value="week" ${draft.expiry==='week'?'selected':''}>一周后</option></select></label></div><div class="publish-rule">${I('clock',18)} 课间与放学展示，上课时自动收起普通内容。</div><button class="btn primary" data-server-write ${bridge.connected&&bridge.state!=='online'?'disabled':''}>预览并确认发布 ${I('arrow',17)}</button><button type="button" class="text-link" data-r2="notice-new">指定展示时段 / 更多设置</button></form>`}<p class="r2-footnote">${bridge.connected?'已连接本地实验服务，发布范围由服务身份和班级规则决定。':'当前为本机演示，角色切换不构成身份认证。'}</p></section><aside class="publish-aside"><div class="teacher-live-preview"><span class="eyebrow">ON THE CLASSROOM SCREEN</span><div class="teacher-preview-head"><span id="teacher-live-kind">${kindName[draft.kind]}</span><span>课间预览</span></div><p id="teacher-live-message">${esc(draft.message||'你写下的话，会这样安静地出现在课间。')}</p><small>仅预览 · 确认发布前不会进入公共屏</small></div><div class="aside-step"><span>01</span><div><h3>内容只输入一次</h3><p>公共屏和学习资源页读取同一份本机内容。</p></div></div><div class="aside-step"><span>02</span><div><h3>课上留白，课间出现</h3><p>展示时段与到期时间始终可查。教师控制屏幕模式。</p></div></div><div class="aside-step"><span>03</span><div><h3>说错了，可以改</h3><p>修改、撤回保留本机操作记录。断网也能用。</p></div></div><div class="teacher-course"><span class="eyebrow">COURSE CONTEXT</span><h3>课程提示来自教师</h3><p>${esc(pub.course.next||'待设置')} · ${pub.course.conflict?'存在冲突':pub.course.confirmed?'已手动确认':'待手动确认'}</p>${act('核对课程提示','course','text-link')}</div></aside></div><section class="notice-list-section"><div class="section-heading"><h2>已经说过的话</h2><div class="segmented"><button data-r2="notice-filter:active" aria-pressed="${noticeFilter==='active'}">当前与待展示</button><button data-r2="notice-filter:archive" aria-pressed="${noticeFilter==='archive'}">到期与撤回</button></div></div>${list.map(n=>`<article class="notice-manage"><span class="notice-kind">${I(n.kind==='resource'?'book':n.kind==='activity'?'star':'edit',23)}</span><div><span class="badge">${stateName[statusOf(n)]} · ${kindName[n.kind]}</span><h3>${esc(n.title)}</h3><p>${esc(n.scope)} · ${roleName[n.publisherRole]}演示 · ${date(n.startAt)} — ${date(n.endAt)}</p><small>v${n.version||1} · ${n.showIn.map(x=>modeName[x]).join(' / ')}展示 · ${n.review==='approved'?'审核通过':'等待接收端审核'}</small></div><div class="notice-actions">${pub.role!=='student'&&(pub.role==='admin'||n.publisherRole==='teacher')?`${n.review==='pending'?act('审核','notice-review:'+n.id,'outline'):''}${act('修改','notice-edit:'+n.id,'text-link')}${n.status!=='withdrawn'?act('撤回','notice-withdraw:'+n.id,'text-link'):''}`:''}</div></article>`).join('')||'<p class="empty-state">这里暂时没有内容。</p>'}</section><div class="public-controls">${act('导出公共演示内容包','export-public','outline','download')}${pub.role!=='student'?'<label class="btn outline import-label">导入待审内容包<input type="file" id="public-import" accept="application/json,.json"></label>':''}${act('查看发布审计','public-audit','text-link')}</div><p class="r2-footnote">公共包不含私人思路、书架、成绩、名单或学习时长。导入内容先进入待审区。${bridge.connected?'本地 HTTP/SSE 服务会同步授权范围内的修改与撤回。':'当前为本机演示；连接本地实验服务后可验证跨窗口同步。'}</p></main>`}
 function tickScreen(){const now=Date.now(),mono=performance.now();if(Math.abs((now-lastClock)-(mono-lastTick))>60000&&!clockFault){clockFault=true;pub.mode='class';pub.hidden=true;saveC();refresh();toast('设备时间出现跳变。内容已收起，请教师核对时间后手动恢复。');return}lastClock=now;lastTick=mono;document.querySelectorAll('[data-screen-clock]').forEach(e=>e.textContent=new Date(now).toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}));document.querySelectorAll('[data-activity-countdown]').forEach(e=>{const remaining=Math.max(0,Date.parse(e.dataset.activityCountdown)-now),hours=Math.floor(remaining/3600000);e.textContent=remaining>0?`距离演示活动 ${Math.floor(hours/24)} 天 ${hours%24} 小时 · ${date(e.dataset.activityCountdown)}`:'演示活动时间已到 · 请核对实际安排'});const display=$('#class-tool-timer');if(display){const left=classTimer.end?Math.max(0,Math.ceil((classTimer.end-now)/1000)):classTimer.left;display.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;if(classTimer.end&&left===0){classTimer={end:0,left:0};$('#timer-toggle-label').textContent='重新开始'}}if((homework.tick()||now%10000<1100)&&!screenHidden&&$('#screen-content')){const focus=document.activeElement;$('#screen-content').innerHTML=screenContent();if(focus?.dataset.r2)document.querySelector(`[data-r2="${focus.dataset.r2}"]`)?.focus();document.querySelectorAll('[data-screen-clock]').forEach(e=>e.textContent=new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit',hour12:false}))}}
 const inputDate=s=>{const d=new Date(s);return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16)};
 function noticeForm(key){ensureWrite();if(pub.role==='student')throw Error('学生演示角色没有发布权限。');const n=pub.notices.find(x=>x.id===key)||{};modal(key?'修改这条公共内容':'安排一条公共内容',`<form data-r2-form="notice" data-id="${esc(n.id||'')}"><input type="hidden" name="version" value="${n.version||1}"><div class="form-columns"><label>类型<select name="kind">${Object.entries(kindName).map(([k,l])=>`<option value="${k}" ${n.kind===k?'selected':''}>${l}</option>`).join('')}</select></label><label>范围<select name="scope">${(pub.role==='admin'?SCOPES:[pub.scope]).map(s=>`<option ${n.scope===s?'selected':''}>${s}</option>`).join('')}</select></label></div><label>标题<input name="title" required maxlength="100" value="${esc(n.title||'')}"></label><label>正文<textarea name="body" required maxlength="2000">${esc(n.body||'')}</textarea></label><div class="form-columns"><label>开始展示<input type="datetime-local" name="startAt" required value="${inputDate(n.startAt||Date.now())}"></label><label>到期归档<input type="datetime-local" name="endAt" required value="${inputDate(n.endAt||Date.now()+86400000)}"></label></div><label>活动开始时间（可选，仅公共活动使用）<input type="datetime-local" name="eventAt" value="${n.eventAt?inputDate(n.eventAt):''}"></label><div class="form-columns"><label>展示状态<select name="mode"><option value="both">课间与放学</option><option value="break" ${n.showIn?.length===1&&n.showIn[0]==='break'?'selected':''}>仅课间</option><option value="after" ${n.showIn?.length===1&&n.showIn[0]==='after'?'selected':''}>仅放学</option></select></label><label>优先级<select name="priority"><option value="normal">普通</option>${pub.role==='admin'?`<option value="urgent" ${n.priority==='urgent'?'selected':''}>紧急 · 授权管理员演示</option>`:''}</select></label></div>${pub.role==='admin'?`<label>紧急原因（紧急内容必填）<input name="reason" maxlength="500" value="${esc(n.reason||'')}"></label>`:''}<p class="muted">${roleName[pub.role]}演示角色。所有内容均为 DEMO，下一步确认后仅在本机生效。</p><button class="btn primary">预览发布</button></form>`,true)}
 function previewNotice(n){draftNotice=n;modal('确认这条内容，再让它出现。',`<div class="notice-preview"><span class="pill">${kindName[n.kind]} · ${esc(n.scope)}</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p></div><p>展示：${date(n.startAt)} — ${date(n.endAt)}<br>状态：${n.showIn.map(x=>modeName[x]).join(' / ')} · ${n.priority==='urgent'?'紧急（管理员授权演示）':'普通'}<br>发布者：${roleName[pub.role]}演示角色</p><p class="muted">没有学校授权连接，不向外部分发。确认后直接进入本机的已审演示内容。</p>${act(bridge.connected?'确认发布到本地服务':'确认发布到本机','publish-confirm','primary')}${bridge.connected?act('提交管理员审核','submit-review','outline'):''}`)}

 document.addEventListener('click',async e=>{const el=e.target.closest('[data-r2]');if(!el)return;const [cmd,key]=el.dataset.r2.split(':');try{switch(cmd){
 case 'focus-open':if(!active()&&!personal.focus){gentle();break}if(!personal.focus||personal.focus.status==='done')personal.focus=startFocus(active());personal.focusDesk=true;saveP();refresh();break;
 case 'focus-leave':personal.focus=pauseFocus(personal.focus);personal.focusDesk=false;saveP();refresh();break;
 case 'focus-duration':if(personal.focus?.status!=='running'&&[5,15,25,45].includes(Number(key))){personal.focus={...personal.focus,minutes:Number(key),remaining:Number(key)*60000,status:'paused',startedAt:0,reason:''};saveP();refresh()}break;
 case 'focus-toggle':personal.focus=personal.focus.status==='running'?pauseFocus(personal.focus):resumeFocus(personal.focus);saveP();refresh();break;
 case 'focus-wrap':wrapFocus();break;
 case 'tools':personal.toolsOnly=!personal.toolsOnly;saveP();refresh();break;
 case 'space':if(PLACES[key]){personal.place=key;saveP();refresh();$('#thought-workspace')?.scrollIntoView({block:'nearest'})}break;
 case 'gentle':gentle();break;case 'suggest':$('#gentle-next').value=['翻开上次停下的那一页','读一遍昨天没弄懂的题','写下目前已经知道的一点'][Number(key)];break;
 case 'space-tool':if(personal.place==='tree'){shelfForm();$('#dialog [name=after]').value=personal.spaceNotes.tree||''}else if(personal.place==='library')thoughtForm(active()?.id);else if(personal.place==='rain'){personal.toolsOnly=true;saveP();refresh();$('#space-note')?.focus()}else{personal.startDraft={title:(personal.spaceNotes.pond||'').slice(0,100),next:''};saveP();gentle()}break;
 case 'thought':thoughtForm(key);break;case 'resume':$('#thought-workspace')?.scrollIntoView({block:'center'});$('#space-note')?.focus();break;
 case 'shelf-new':shelfForm();break;case 'shelf-edit':shelfForm(key);break;
 case 'shelf-delete':modal('删除这条私人记录？',`<p>仅删除本机记录，无法撤销。你可以先导出备份。</p>${act('确认删除','shelf-remove:'+key,'primary')}`);break;
 case 'shelf-remove':personal.shelf=personal.shelf.filter(x=>x.id!==key);saveP();close();refresh();break;
 case 'history':modal('留下的思路',`<div class="thought-history">${personal.thoughts.map(t=>`<article><h3>${esc(t.title)}</h3><p>${esc(t.next)}</p><div class="row-actions">${act('接回桌面','thought-select:'+t.id,'outline')}${act('编辑','thought:'+t.id,'text-link')}${act('删除','thought-delete:'+t.id,'text-link')}</div></article>`).join('')||'<p>还没有思路记录。先从一件小事开始。</p>'}</div>`);break;
 case 'thought-select':personal.active=key;saveP();close();location.hash='study';refresh();break;
 case 'thought-delete':modal('删除这段思路？',`<p>这不会删除空间便笺或书架记录。</p>${act('确认删除','thought-remove:'+key,'primary')}`);break;
 case 'thought-remove':personal.thoughts=personal.thoughts.filter(t=>t.id!==key);if(personal.active===key)personal.active=null;saveP();close();refresh();break;
 case 'export-private':download(new Blob([JSON.stringify({format:'haiz-private-study',version:2,data:personal},null,2)],{type:'application/json'}),'HAIZ-私人学习备份.json');break;
 case 'private-restore':personal=privateState(pendingImport);saveP();close();refresh();toast('私人备份已恢复，仅存本机。');break;
 case 'clear-private':modal('清除 Study 2.0 的私人记录？',`<p>思路卡、思考书架和四个空间的便笺会删除。第一轮内容和公共通知不受影响。请先导出需要保留的内容。</p>${act('确认清除私人记录','private-reset','primary')}`);break;
 case 'private-reset':personal=emptyPrivate();saveP();close();refresh();break;
 case 'print':window.print();break;
 case 'public-activity':{const n=pub.notices.find(x=>x.id===key);if(n)modal(n.title,`<span class="pill">已审公共活动 · 演示</span><p>${esc(n.body)}</p><p class="muted">${esc(n.scope)} · 到期 ${date(n.endAt)}。线下参与方式以正文为准，无需手机扫码。</p>`);break}
 case 'resource-start':{const n=pub.notices.find(x=>x.id===key);if(!n)break;personal.startDraft={title:n.title,next:''};saveP();gentle(2);break}
 case 'resource-print':{const n=pub.notices.find(x=>x.id===key);if(!n)break;modal(n.title,`<article class="resource-print"><span>公共选学资源 / 演示</span><p>${esc(n.body)}</p><p>在纸上想，不必提交个人记录。</p></article>${act('打印资源','print','primary')}`);break}
 case 'r2room':{const host=$('#r2-room');if(!host)break;if(host.firstChild){host.replaceChildren();el.innerHTML=I('play',18)+' 走近三维窗台'}else{host.innerHTML='<iframe title="可收起的独立三维课间窗台，AGPL-3.0" src="room/scene/index.html?quality=low" loading="lazy"></iframe>';el.innerHTML=I('close',18)+' 收起三维窗台'}break}
 case 'notice-next':noticeCursor++;refresh();break;case 'notice-prev':{const count=displayNotices(pub).filter(n=>n.kind==='notice').length;noticeCursor=(noticeCursor-1+count)%Math.max(1,count);refresh();break}
 case 'mode':homework.clearSimulation();pub.homeworkAuto=false;noticeCursor=0;adapterFollow=false;pub.mode=Object.hasOwn(modeName,key)?key:'class';pub.hidden=false;screenHidden=false;saveC();refresh();break;
 case 'screen-hide':pub.hidden=true;screenHidden=true;saveC();if(document.fullscreenElement)await document.exitFullscreen();$('#screen-content').hidden=true;$('#screen-curtain').hidden=false;break;
 case 'screen-show':pub.hidden=false;screenHidden=false;clockFault=false;saveC();refresh();break;
 case 'fullscreen':try{if(document.fullscreenElement)await document.exitFullscreen();else await $('#main').requestFullscreen()}catch{toast('当前浏览器不支持网页全屏，可使用浏览器全屏按钮。')}break;
 case 'notice-template':if($('[data-r2-form=quick-publish] [name=message]')?.value.trim()){modal('替换当前草稿？',`<p>将用「${noticeTemplates[Number(key)]?.name||''}」模板替换当前文字。已发布的通知不会改变。</p>${act('使用这个模板','template-confirm:'+key,'primary')}`)}else applyTemplate(Number(key));break;case 'template-confirm':applyTemplate(Number(key));break;
 case 'notice-new':noticeForm();break;case 'notice-edit':noticeForm(key);break;
 case 'notice-filter':noticeFilter=key;refresh();break;
 case 'submit-review':case 'publish-confirm':if(!draftNotice)break;ensureWrite();if(bridge.connected)await bridge.write('/api/notices',{...draftNotice,submitForReview:cmd==='submit-review'});else pub=publishNotice(pub,draftNotice,pub.role);draftNotice=null;try{localStorage.removeItem(draftKey())}catch{}saveC();close();refresh();toast(cmd==='submit-review'?'已提交服务端待审区，管理员通过后才能显示。':'已发布到演示范围。上课模式不会展示普通通知。');break;
 case 'notice-withdraw':modal('撤回这条公共内容？',`<p>会立即从本机公共屏和公共资源页消失。已导出的副本不会自动撤回。</p>${act('确认撤回','withdraw-confirm:'+key,'primary')}`);break;
 case 'withdraw-confirm':ensureWrite();if(bridge.connected)await bridge.write('/api/notice-action',{id:key,version:pub.notices.find(n=>n.id===key)?.version,operation:'withdraw'});else pub=changeNotice(pub,key,'withdraw',pub.role);saveC();close();refresh();break;
 case 'notice-review':{const n=pub.notices.find(x=>x.id===key);if(!n)break;modal('核对导入内容',`<span class="pill">${esc(n.scope)} · 演示包</span><h3>${esc(n.title)}</h3><p>${esc(n.body)}</p><p>${date(n.startAt)} — ${date(n.endAt)} · ${n.priority==='urgent'?'紧急':'普通'}</p><p class="muted">请核查正文、范围与时段。本机确认不等于学校授权。</p>${act('审核通过 · 本机展示','approve-confirm:'+key,'primary')}`);break}
 case 'approve-confirm':ensureWrite();if(bridge.connected)await bridge.write('/api/notice-action',{id:key,version:pub.notices.find(n=>n.id===key)?.version,operation:'approve'});else pub=changeNotice(pub,key,'approve',pub.role);saveC();close();refresh();break;
 case 'export-public':download(new Blob([JSON.stringify(exportPublic(pub),null,2)],{type:'application/json'}),'HAIZ-公共演示内容包.json');break;
 case 'import-confirm':if(bridge.connected)throw Error('服务连接模式不接受未签名文件发布。请断开后在隔离本机演示中导入。');pub=importPublic(pub,pendingImport,pub.role);saveC();pendingImport=[];close();refresh();toast('内容已进入待审区。逐条核对通过后才会展示。');break;
 case 'public-audit':modal('本机发布记录',`<p class="muted">演示日志可被本机修改，不是防篡改审计。</p><ol class="audit-list">${pub.audit.slice(-40).reverse().map(a=>`<li><span>${esc(a.message)} · ${roleName[a.role]||esc(a.role)}</span><time>${date(a.at)}</time></li>`).join('')||'<li>还没有发布操作。</li>'}</ol>`,true);break;
 case 'course':ensureWrite();if(pub.role==='student')throw Error('学生演示不能设置课程提示。');modal('核对课程附加提示',`<form data-r2-form="course"><p class="muted">未连接 ClassIsland。以下仅为教师手动示例，不修改正式课表。</p><label>下一节科目 / 次日准备主题<input name="next" maxlength="50" ${bridge.connected?'readonly':''} required value="${esc(pub.course.next)}"></label><label>教师提供的准备事项<textarea name="note" maxlength="300">${esc(pub.course.note)}</textarea></label><label class="checkbox-label"><input type="checkbox" name="conflict" ${pub.course.conflict?'checked':''}>发现与正式安排冲突，暂停显示增强提示</label><label class="checkbox-label"><input type="checkbox" name="confirmed">我已核对来源，并确认本次演示内容</label><button class="btn primary">保存核对结果</button></form>`);break;
 case 'connect-dialog':connectDialog();break;
 case 'sync-pull':await bridge.pull();close();refresh();break;
 case 'sync-disconnect':bridge.disconnect();pub.bridge=null;pub.sync=null;pub.role='teacher';pub.scope=SCOPES[0];saveC();close();refresh();break;
 case 'adapter':await bridge.write('/api/adapter',{state:['class','break','after'].includes(key)?key:'class',available:key!=='unavailable',conflict:key==='conflict'});close();refresh();break;
 case 'class-tools':modal('用完，就收起来。',`<div class="class-tools-panel"><h3>课堂计时</h3><div id="class-tool-timer">05:00</div><div class="row-actions">${act('<span id="timer-toggle-label">开始 / 暂停</span>','class-timer','primary')}${act('重置 5 分钟','class-timer-reset','outline')}</div><p class="muted">静音，不触发系统通知。此工具独立于 ClassIsland 的课表提醒。</p><form data-r2-form="temporary"><label>只在当前窗口显示的临时提示<input name="text" maxlength="160" required placeholder="请先独立阅读，再交流。"></label><button class="btn outline">显示提示</button></form><a class="text-link" href="#lesson" data-action="close">教学文件快捷入口 ↗</a>${act('纯净课堂模式','pure-class','text-link')}${act('临时白板','blank','text-link')}</div>`);tickScreen();break;
 case 'class-timer':classTimer=classTimer.end?{end:0,left:Math.max(0,Math.ceil((classTimer.end-Date.now())/1000))}:{end:Date.now()+(classTimer.left||300)*1000,left:classTimer.left||300};tickScreen();break;
 case 'class-timer-reset':classTimer={end:0,left:300},focusTickAt=Date.now(),focusMono=performance.now(),noticeCursor=0;tickScreen();break;
 case 'pure-class':adapterFollow=false;pub.mode='class';saveC();close();refresh();break;
 case 'blank':modal('纯净提示板',`<div class="blank-board" contenteditable="true" role="textbox" aria-label="可输入临时文字的纯净提示板">点击写一句话</div><p class="muted">临时内容不保存。Esc 关闭。</p>`,true);break;
 }}catch(err){toast(err.message)}});
 document.addEventListener('submit',async e=>{const f=e.target;if(!f.dataset.r2Form)return;e.preventDefault();const d=Object.fromEntries(new FormData(f)),form=f.dataset.r2Form;try{switch(form){
 case 'focus-wrap':{const f=personal.focus,a=personal.thoughts.find(x=>x.id===f.thoughtId);personal=saveThought(personal,{...a,id:a?.id,title:a?.title||f.title,understood:d.understood,next:d.next});personal.focus={...f,status:'done',startedAt:0,checkpoint:d.understood};personal.focusDesk=false;saveP();close();refresh();toast('这一段已经收好。回来时，从下一步继续。');break}
 case 'connect':await bridge.connect(d.token.trim());close();refresh();toast('已连接本地实验服务。课程来源为模拟适配器。');break;
 case 'thought':personal=saveThought(personal,{...d,id:f.dataset.id});saveP();close();refresh();toast('思路已经留下，下次打开会回到桌面。');break;
 case 'gentle-1':if(!d.title.trim())throw Error('写下一件想做的事就好。');personal.startDraft={title:d.title.trim(),next:''};saveP();gentle(2);break;
 case 'gentle-2':personal=saveThought(personal,{title:personal.startDraft.title,next:d.next});personal.startDraft={};saveP();close();location.hash='study';refresh();$('#thought-workspace')?.scrollIntoView({block:'center'});$('#space-note')?.focus();break;
 case 'shelf':{if(!d.title.trim()||!d.after.trim())throw Error('写下名字和此刻的理解。');const record={...d,id:f.dataset.id||makeId(),updatedAt:new Date().toISOString()};personal.shelf=[record,...personal.shelf.filter(x=>x.id!==record.id)];saveP();close();refresh();break}
 case 'quick-publish':{ensureWrite();d.scope=d.scope||pub.scope;const message=d.message.trim();if(!message)throw Error('先写下想提醒的事。');pub.scope=d.scope;saveC();let end=new Date();if(d.expiry==='tomorrow'){end.setDate(end.getDate()+1);end.setHours(18,0,0,0)}else if(d.expiry==='week')end=new Date(Date.now()+7*86400000);else end.setHours(23,59,59,0);previewNotice({kind:d.kind,title:message.split(/\n/)[0].slice(0,100),body:message,scope:d.scope,startAt:new Date().toISOString(),endAt:end.toISOString(),priority:'normal',showIn:['break','after'],reason:''});break}
 case 'notice':{const n={...d,eventAt:d.eventAt?new Date(d.eventAt).toISOString():'',id:f.dataset.id||undefined,startAt:new Date(d.startAt).toISOString(),endAt:new Date(d.endAt).toISOString(),showIn:d.mode==='both'?['break','after']:[d.mode]};publishNotice(pub,n,pub.role);previewNotice(n);break}
 case 'course':if(pub.role==='student')throw Error('没有设置权限');ensureWrite();if(bridge.connected){if(d.conflict==='on')throw Error('已发现冲突，请管理员核对课程来源。未发布增强提示。');await bridge.write('/api/course-note',{subject:pub.bridge?.next,text:d.note.trim(),confirmed:d.confirmed==='on'})}else pub.course={next:d.next.trim(),note:d.note.trim(),conflict:d.conflict==='on',confirmed:d.confirmed==='on'&&d.conflict!=='on'};pub=audit(pub,pub.role,pub.course.conflict?'标记课程冲突，增强提示暂停':'更新教师手动课程提示');saveC();close();refresh();break;
 case 'temporary':modal('临时提示',`<div class="temporary-prompt">${esc(d.text)}</div><p class="muted">仅当前窗口，不保存、不分发。Esc 关闭。</p>`,true);break;
 }}catch(err){toast(err.message)}});
 document.addEventListener('visibilitychange',()=>{if(document.hidden&&personal.focus?.status==='running'){personal.focus=pauseFocus(personal.focus,Date.now(),'页面离开了，计时已暂停。回来时继续就好。');saveP();if(current==='study')refresh()}});
 document.addEventListener('change',e=>{if(e.target.id==='follow-adapter'){adapterFollow=e.target.checked;if(adapterFollow&&!pub.hidden){pub.mode=pub.bridge?.available&&!pub.bridge?.conflict?pub.bridge.state:'class';saveC()}toast(adapterFollow?'已跟随本地模拟课程状态，手动隐藏仍优先。':'已恢复手动模式。');refresh()}if(e.target.id==='r2-role'){pub.role=e.target.value;if(pub.role==='teacher'&&pub.scope===SCOPES[2])pub.scope=SCOPES[0];saveC();refresh()}if(e.target.id==='r2-scope'){pub.scope=e.target.value;saveC();refresh()}});
 window.addEventListener('storage',e=>{if(e.key===PUBLIC_KEY&&!bridge.connected){pub=read(PUBLIC_KEY,publicState);if(current==='classroom'){if(pub.hidden){screenHidden=true;if($('#screen-content'))$('#screen-content').innerHTML=screenContent()}else if(!screenHidden&&$('#screen-content'))$('#screen-content').innerHTML=screenContent()}else if(['resources','homework','assignments'].includes(current))refresh();if($('#r2-public-activities'))$('#r2-public-activities').outerHTML=publicActivities()}if(e.key===PRIVATE_KEY){personal=read(PRIVATE_KEY,privateState);if(['study','shelf'].includes(current)&&!$('#dialog')?.open&&document.activeElement?.tagName!=='TEXTAREA')refresh()}});
 window.addEventListener('message',e=>{const frame=$('#r2-room iframe');if(!frame||e.origin!==location.origin||e.source!==frame.contentWindow||e.data?.channel!=='haiz:windowsill:v1')return;if(e.data.type==='ready'){for(const msg of [{type:'quality',value:'low'},{type:'preset',id:personal.place==='rain'?'rainnight':personal.place==='tree'?'dusk':'morning'},{type:'pause',value:matchMedia('(prefers-reduced-motion: reduce)').matches}])frame.contentWindow.postMessage({channel:'haiz:windowsill:v1',...msg},location.origin)}if(e.data.type==='error'){frame.remove();toast('三维暂不可用，私人学习工具仍可使用。')}});
 return {render,mount,leave,publicActivities,routes:['study','shelf','paper','resources','classroom','teach','homework','assignments']};
}
